<?php
require '../config/config.php'; role('anggota');$uid=$_SESSION['u']['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$code=trim($_POST['copy_code']??'');if(!$code)throw new Exception('Masukkan atau scan barcode buku.');$n=$pdo->prepare('SELECT COUNT(*) FROM loans WHERE user_id=? AND returned_at IS NULL');$n->execute([$uid]);if((int)$n->fetchColumn() >= (int)setting('max_loans',2))throw new Exception('Batas peminjaman sudah tercapai.');$late=$pdo->prepare("SELECT COUNT(*) FROM loans WHERE user_id=? AND returned_at IS NULL AND due_date<CURDATE()");$late->execute([$uid]);if($late->fetchColumn())throw new Exception('Anda masih memiliki buku yang terlambat. Kembalikan terlebih dahulu.');$q=$pdo->prepare("SELECT c.id,c.status,b.title FROM copies c JOIN books b ON b.id=c.book_id WHERE c.code=?");$q->execute([$code]);$c=$q->fetch();if(!$c)throw new Exception('Barcode buku tidak ditemukan.');if($c['status']!=='tersedia')throw new Exception('Buku tidak tersedia untuk dipinjam.');$due=(new DateTime())->modify('+'.(int)setting('loan_days',7).' days')->format('Y-m-d');$pdo->beginTransaction();$pdo->prepare('INSERT INTO loans(user_id,copy_id,loan_date,due_date) VALUES(?,?,CURDATE(),?)')->execute([$uid,$c['id'],$due]);$pdo->prepare("UPDATE copies SET status='dipinjam' WHERE id=?")->execute([$c['id']]);$pdo->commit();setmsg("Berhasil meminjam: {$c['title']}. Jatuh tempo $due");header('Location:dashboard.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();setmsg($e->getMessage(),'danger');}
}
?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Pinjam Buku</title><link rel=stylesheet href=../public/style.css></head><body><?php include 'nav.php'; ?><main style="max-width:1100px;margin:0 auto;padding:24px"><h1>📖 Pinjam Buku</h1><?php msg()?><div class=form><h3>Scan Barcode Buku</h3><p>Gunakan scanner barcode USB atau ketik kode eksemplar, misalnya <b>BK-0001-01</b>.</p><form method=post><label>Barcode Buku</label><input name=copy_code autofocus required placeholder="Scan barcode di sini"><button>🔄 Proses Peminjaman</button></form></div><br><div class=card><h3>Aturan Peminjaman</h3><ul><li>Maksimal <?=e(setting('max_loans',2))?> buku aktif.</li><li>Jatuh tempo <?=e(setting('loan_days',7))?> hari sejak peminjaman.</li><li>Buku yang terlambat harus dikembalikan terlebih dahulu.</li></ul></div></main></body></html>
